"""Автономный двуязычный просмотр фиксации, оценки и диагностических отказов."""
import json


def markdown(sealed, evaluation, entries):
    d = sealed["diagnostics"]; w = d["witness_screening"]["counts"]
    novel = len(sealed["predictions"]["free"])
    matched = evaluation["modes"]["free"]["matched_candidate_count"]
    accepted = sum(d["legacy"][mode]["accepted_rules"] for mode in ("semantic","graph"))
    analogy_result = ("Ни одна не образует полный допустимый перенос с третьей предпосылкой."
        if not d["analogy"]["examined_analogy_combinations"] else
        f'Проверено полных комбинаций для аналогии: {d["analogy"]["examined_analogy_combinations"]}.')
    outcome = ("Критерий успеха не достигнут." if not matched else
               "Получены отладочные совпадения; независимый научный критерий ещё не подтверждён.")
    lines = ["# Первый ограниченный свободный прогноз", "",
        f"Результат: {novel} новых кандидатов и {matched} новых подтверждённых знаний. {outcome} Это проверка конкретного консервативного генератора на известных картах, а не доказательство невозможности свободного прогнозирования.", "",
        "## Зафиксированный корпус", "",
        "Вопрос об IL-6 не задан. Тематическая граница — старение, когнитивные нарушения и связанные механизмы. Используются пять ранее утверждённых GOLD-карт схемы 6, опубликованных до конца 2022 года. Карты и исходники не пересобирались.", "",
        "| Источник | Дата публикации | Запуск карты |", "|---|---|---|"]
    for entry in entries:
        lines.append(f'| {entry["pmcid"]} | {entry["published_on"]} | {entry["reference"]["run_id"]} |')
    lines += ["", f'Вход: {sealed["source_knowledge_count"]} блоков, {sealed["source_statement_count"]} компонентов утверждений; {sealed["eligible_statement_count"]} допущены к обучению по существующим ограничениям семантики. Различные публикации считаются группами происхождения, а не автоматически независимыми научными подтверждениями. Обзоры могут цитировать одни первичные исследования.', "",
        "## Генерация", "",
        "Первый оператор ищет повторяющийся шаблон с одним заключением и до трёх предпосылок, поддержанный не менее чем двумя группами происхождения. Применяются два источниковых режима: семантика и полные группы зависимостей. Совместные предпосылки и альтернативные пути различаются.", "",
        "Второй оператор предлагает проверку по аналогии: P(a,x), P(b,x), Q(a,y) → гипотеза Q(b,y). Это не дедукция и не правило транзитивности ассоциаций. Сохраняются область, отрицание, модальность и статус; числовые эффекты не предсказываются, участники разных когорт не подменяются. Исключаются уже известные факты, их обратная запись для симметричных ассоциаций, ослабленные известные утверждения и явные противоречия источникам.", "",
        "Единый бюджет — максимум 20 новых кандидатов. Пустой прогноз допустим. Ранжирование использует только источники: поддержку, число групп происхождения, число предпосылок и стабильный хеш. Текст/семантика/контроль цитирования цели не участвуют в обучении и ранжировании.", "",
        f'Шаблонов без связей проверено {d["legacy"]["semantic"]["candidate_templates"]}; с полными группами зависимостей — {d["legacy"]["graph"]["candidate_templates"]}. Поддержанных шаблонов: {accepted}. Структурных пар с заменой одной роли — {w.get("single_role_structural_pairs",0)}; из них несовместимы по полной сигнатуре {w.get("different_scope_bundle_pairs",0)}, одинаковую сигнатуру имеют {w.get("same_scope_pairs",0)}. {analogy_result}', "",
        f'Различия числовых/прочих атрибутов: {w.get("different_attributes_pairs",0)} пар; области/времени/условий: {w.get("different_context_pairs",0)}; логики: {w.get("different_logic_pairs",0)}. Эти множества пересекаются. Различие свободно записанных условий само по себе не доказывает научную несовместимость: текущий генератор требует точного совпадения и отказывается при недоказанной сопоставимости.', "",
        "## Раздельная оценка", "",
        f'Прогноз: `{sealed["run_id"]}`. Оценка: `{evaluation["evaluation_id"]}`. SHA-256 зафиксированного прогноза: `{evaluation["binding"]["prediction_sha256"]}`.', "",
        "Квитанция первого процесса содержит только пять источников; квитанция второго — единственную цель. Оценщик сначала проверяет неизменяемую фиксацию и хеши реализации, затем загружает PMC10000452. Прогноз после оценки не пересчитывается. Цель уже была изучена ранее: это отладочный, не слепой опыт.", "",
        "| Режим | Выдано | Полностью совпавшие кандидаты | Полностью покрытые блоки цели |", "|---|---:|---:|---:|"]
    for mode,label in (("free","Свободный прогноз"),("known_union","Известные: первые 20 по хешу"),("frequency","Частотная база: первые 20")):
        m=evaluation["modes"][mode]
        lines.append(f'| {label} | {m["candidate_count"]} | {m["matched_candidate_count"]} | {len(m["fully_covered_target_blocks"])} |')
    lines += ["", f'Всего в источниках {sealed["known_count"]} уникальных нормализованных утверждений. Две базы выбирают по 20 уже известных утверждений; число 20 — объём выдачи, не число совпадений. База по хешу является детерминированным контрольным отбором, не тематическим поиском. Этот опыт не пересчитывает покрытие всем объединением известных утверждений: прежний полный анализ сохранён отдельно.', "",
        "Неизвестный контекст блокирует полную эквивалентность. Частичное совпадение, общий шаблон или совпавшее число не считаются новым предсказанным знанием. Отсутствие в цели не является опровержением. Составные блоки сохраняют логику и проверяются по компонентам без объявления совпавшего компонента совпадением всего блока.", "",
        "## Следующий шаг", "",
        "Переход от заданного вопроса к свободному режиму сам по себе не устранил препятствие: текущие семантические сигнатуры плохо переиспользуются. Нужен небольшой источниковый аудит атомарности, словаря предикатов/ролей и структурированных контекстов. Следует различить истинное расхождение контекста и две формулировки одного условия; целевую статью не использовать для выбора замен. Затем повторить тот же состав корпуса с отдельной версией представления и сравнить изменившиеся отказы. Не добавлять случайные статьи и не удалять отрицания/числа/условия ради совпадений.", "",
        "Научный критерий остаётся прежним: содержательное утверждение отсутствует в обучении, фиксируется до оценки и подтверждается с совместимым контекстом в независимом последующем источнике. Для доказательства работоспособности системы дополнительно нужны повторяемость и преимущество перед базами. PMC10000452 используется только для отладки.", "",
        "В этой поставке сохранены и предварительные фиксации диагностики, созданные до оценки; для просмотра выбран окончательный запуск выше. Карты GOLD, история UI и прежние IL-6-опыты не изменены. Внешних/локальных модельных вызовов и сетевых обращений: 0. Переводы подписей переиспользованы. Расход токенов Codex недоступен и не выдумывался. Требуется экспертная научная проверка."]
    return "\n".join(lines)+"\n"


def render(data):
    encoded = json.dumps(data, ensure_ascii=False, allow_nan=False, separators=(",", ":"))
    return TEMPLATE.replace("__DATA__", encoded.replace("<", "\\u003c").replace("\u2028", "\\u2028").replace("\u2029", "\\u2029"))


TEMPLATE = r'''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Свободный прогноз — пять GOLD-источников</title>
<style>body{font:16px/1.55 system-ui;color:#162336;background:#f3f6fb;max-width:1280px;margin:auto;padding:28px}h1{font-size:30px}button,select,a{font:inherit}button,select,.link{padding:9px 14px;border:1px solid #8797ac;border-radius:8px;background:#fff;color:#162336}button,.link{cursor:pointer}button:hover,.link:hover{background:#e9f0fc}.link{text-decoration:none;display:inline-block}.toolbar{display:flex;gap:10px;flex-wrap:wrap;margin:16px 0}.notice,.card{padding:18px;background:white;border:1px solid #cbd5e1;border-radius:10px;margin:14px 0}.notice{border-left:5px solid #b45309}table{width:100%;border-collapse:collapse;background:white}th,td{padding:12px;text-align:left;border:1px solid #cbd5e1}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:white;padding:18px;max-height:520px;overflow:auto;border:1px solid #cbd5e1}#detail .toolbar button{font-size:14px}mark{background:#ffeda8}.muted{color:#53657b}td button{padding:5px 10px}#fragment{max-height:260px}#source{max-height:430px}button:focus-visible,a:focus-visible,select:focus-visible{outline:3px solid #2563eb}</style>
<header><h1 id="heading"></h1><div class="toolbar"><button id="ru">Русский</button><button id="en">English</button><a class="link" href="report.ru.md">Отчёт / Report</a><a class="link" href="predictions.json">Прогноз JSON</a><a class="link" href="evaluation.json">Оценка JSON</a></div></header>
<p class="notice" id="notice"></p><div id="summary" class="card"></div><table id="metrics"></table>
<div class="toolbar"><label id="mode-label" for="mode"></label><select id="mode"><option value="free">Свободный прогноз / Free forecast</option><option value="known_union">Известные: 20 по хешу / Known: 20 by hash</option><option value="frequency">Частотная база / Frequency baseline</option><option value="diagnostics">Отказы аналогий / Analogy diagnostics</option></select></div>
<p id="explanation" class="muted"></p><table><thead><tr><th id="item-label"></th><th id="status-label"></th><th></th></tr></thead><tbody id="rows"></tbody></table>
<div id="detail" class="card" hidden><h2 id="detail-heading"></h2><div id="proofs" class="toolbar"></div><pre id="details"></pre><h3 id="fragment-heading"></h3><pre id="fragment"></pre><details><summary id="full-source-label"></summary><pre id="source"></pre></details></div>
<details class="card"><summary id="versions-label"></summary><pre id="versions"></pre></details>
<script id="data" type="application/json">__DATA__</script><script>
const D=JSON.parse(document.getElementById('data').textContent),$=id=>document.getElementById(id);let lang='ru',selected=null;
const t=(ru,en)=>lang==='ru'?ru:en, modeName=m=>({free:t('Свободный прогноз','Free forecast'),known_union:t('Известные: 20 по хешу','Known: 20 by hash'),frequency:t('Частотная база','Frequency baseline')}[m]);
function tr(cells){const r=document.createElement('tr');for(const value of cells){const c=document.createElement('td');c.textContent=value;r.append(c)}return r}
function snippet(article,uid){const s=D.sources[article],u=s.units.find(u=>u.id===uid);if(!u)throw Error('Unknown source unit');const chars=Array.from(s.text);$('fragment').textContent=chars.slice(u.start,u.end).join('');$('source').replaceChildren(document.createTextNode(chars.slice(0,u.start).join('')));const mark=document.createElement('mark');mark.textContent=chars.slice(u.start,u.end).join('');$('source').append(mark,document.createTextNode(chars.slice(u.end).join('')));$('fragment').dataset.unit=uid;$('fragment').dataset.article=article;}
function statementText(source,sid,fallback){const s=D.sources[source]?.statements[sid];return s?(lang==='ru'?s.text_ru:s.text):fallback}
function inspect(item,diagnostic=false){selected={item,diagnostic};$('detail').hidden=false;$('details').textContent=JSON.stringify(item,null,2);$('proofs').replaceChildren();
const proofs=diagnostic?[{source_id:item.left.source_id,node_id:item.left.statement_id},{source_id:item.right.source_id,node_id:item.right.statement_id}]:item.premises||item.source_occurrences?.map(p=>({source_id:p.article_id,node_id:p.statement_id,provenance:p.provenance}))||[];
if(!diagnostic){const m=D.evaluation.modes[$('mode').value]?.results.find(r=>r.candidate_id===item.id);for(const x of m?.matches||[])proofs.push({source_id:D.target_article_id,node_id:x.target_statement_id})}
const seen=new Set();for(const p of proofs){const record=D.sources[p.source_id]?.statements[p.node_id];for(const uid of record?.provenance.unit_ids||p.provenance?.unit_ids||[]){const key=p.source_id+'|'+uid;if(seen.has(key))continue;seen.add(key);const b=document.createElement('button');b.textContent=D.sources[p.source_id].pmcid+' · '+(record?.knowledge_id||p.node_id)+' · '+uid;b.onclick=()=>snippet(p.source_id,uid);$('proofs').append(b)}}
$('fragment').textContent='';$('source').replaceChildren();$('proofs').querySelector('button')?.click();}
function render(){document.documentElement.lang=lang;$('heading').textContent=t('Свободный прогноз по пяти GOLD-источникам','Free forecast from five GOLD sources');
$('notice').textContent=t('Новых кандидатов: '+D.sealed.predictions.free.length+'. Критерий успеха пока не достигнут. PMC10000452 — ранее изученный отладочный случай. Модельных вызовов: 0.','Novel candidates: '+D.sealed.predictions.free.length+'. The success criterion is not yet reached. PMC10000452 is a previously inspected debugging case. Model calls: 0.');
$('summary').textContent=t('Блоков источников: ','Source blocks: ')+D.sealed.source_knowledge_count+t(' · утверждений: ',' · statements: ')+D.sealed.source_statement_count+t(' · допустимы для обучения: ',' · eligible for training: ')+D.sealed.eligible_statement_count+t(' · лимит новых кандидатов: 20',' · new-candidate budget: 20');
$('metrics').replaceChildren(tr([t('Режим','Mode'),t('Выдано','Returned'),t('Полные совпадения кандидатов','Equivalent candidates'),t('Покрытые блоки цели','Fully covered target blocks')]));for(const m of ['free','known_union','frequency']){const e=D.evaluation.modes[m];$('metrics').append(tr([modeName(m),e.candidate_count,e.matched_candidate_count,e.fully_covered_target_blocks.length]))}
for(const [id,ru,en] of [['mode-label','Показать','Show'],['item-label','Утверждение / диагностическая пара','Statement / diagnostic pair'],['status-label','Результат','Result'],['detail-heading','Семантика и происхождение','Semantics and provenance'],['fragment-heading','Исходный фрагмент (английский)','Source fragment (English)'],['full-source-label','Полный источник с выделением','Full source with highlighted fragment'],['versions-label','Версии, ограничения и квитанции','Versions, constraints and receipts']])$(id).textContent=t(ru,en);
const mode=$('mode').value,diagnostic=mode==='diagnostics';$('rows').replaceChildren();$('detail').hidden=true;selected=null;
$('explanation').textContent=diagnostic?t('Это отклонённые структурные сходства, а не прогнозы или доказанные противоречия. Различия текста условий могут требовать проверки нормализации.','These are rejected structural similarities, not forecasts or established contradictions. Wording differences may require a normalization audit.'):mode==='free'?t('Аналогия — гипотеза. При недостаточных основаниях выдача остаётся пустой.','Analogy is a hypothesis. Insufficient grounds result in an empty forecast.'):t('20 — число выданных известных утверждений, а не совпадений. Это контрольная база, не новые знания.','20 is the number of returned known statements, not matches. This is a baseline, not novel knowledge.');
const items=diagnostic?D.sealed.diagnostics.witness_screening.examples:D.sealed.predictions[mode];for(const item of items){const row=tr([diagnostic?statementText(item.left.source_id,item.left.statement_id,item.left.text)+' ↔ '+statementText(item.right.source_id,item.right.statement_id,item.right.text):item.source_occurrences?.map(p=>statementText(p.article_id,p.statement_id,p.display_text)).join('\n')||JSON.stringify(item.atom),diagnostic?t('Перенос отклонён','Transfer rejected'):D.evaluation.modes[mode].results.find(r=>r.candidate_id===item.id)?.matches.map(m=>m.target_knowledge_id+' · '+m.relation).join('; ')||t('Полного совпадения нет','No equivalent match')]);const td=document.createElement('td'),b=document.createElement('button');b.textContent=t('Открыть','Inspect');b.onclick=()=>inspect(item,diagnostic);td.append(b);row.append(td);$('rows').append(row)}
if(!items.length)$('rows').append(tr([t('Нет кандидатов при зафиксированных ограничениях.','No candidates under the frozen constraints.'),'','']));
$('versions').textContent=JSON.stringify({binding:D.sealed.binding,seal:D.seal_proof,evaluation:D.evaluation.binding,source_reads:D.receipts.seal,evaluator_reads:D.receipts.evaluate,diagnostics:D.sealed.diagnostics},null,2);}
$('ru').onclick=()=>{lang='ru';render()};$('en').onclick=()=>{lang='en';render()};$('mode').onchange=render;render();
</script></html>'''
